# 🧾️ Builds ../🗑️generated/pwp0-results.json (the measured numbers and prose blocks plan_edit.py inserts) from the closure logs and the oracle notes.
import json, os, re, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import crates as C
G = C.GEN
def rows(path):
    out = {}
    for l in open(path, encoding='utf-8'):
        p = l.rstrip('\n').split('\t')
        if len(p) >= 9 and p[1] == 'files': out[p[0]] = (int(p[2]), int(p[4]), int(p[6]), int(p[8]))
    return out
def fmt(r): return '%d / %s / %s' % (r[0], f'{r[1]:,}', f'{r[2]:,}') + (' / %d embedded' % r[3] if r[3] else '')
def main():
    s = rows(G + '/pwp0-closure-start.log'); e = rows(G + '/pwp0-closure-end.log')
    plan = {'lib native': '185 / 6,007,520 / 83,182', 'lib wasm32-wasip2': '189 / 6,075,698 / 84,493', 'lib wasm32-unknown-unknown': '185 / 6,007,520 / 83,256', 'lib native canvas': '185 / 6,007,520 / 83,194',
            'lib native testing-features': '211 / 6,512,773 / 88,660 / 10 embedded', 'test native': '729 / 12,793,280 / 145,762 / 270 embedded', 'test wasm32-wasip2': '733 / 12,861,458 / 147,043 / 270 embedded', 'test native all-features': '731 / 12,806,193 / 145,841 / 271 embedded'}
    t = ['**[WP0 change] Re-measure (files / bytes / active lines), `pwp0-tools/closure.ts`, 2026-10-15; "start" is before the first WP0 edit, "end" after the hubs and the facade macro mounts.**', '', '| closure | plan | start | end |', '|---|---|---|---|']
    for k in plan: t.append(f'| {k} | {plan[k]} | {fmt(s[k])} | {fmt(e[k])} |')
    t += ['', 'Drift start against plan: +21 active lines and +2,790 bytes in the lib closure, +21 lines and +3,070 bytes in the test closure, same file counts. By file (`appendix_a_drift.py`): the root `🦀️.rs` 940 to 960 lines (+3,312 bytes: the `InstanceExtensions` alias and the `semio-framework-ui-layout` / `-ui-declaration` / `-ui-scene` re-exports that replaced `pub use ui_wgpu::wgpu::*`), `🪟️window-kits/🌍️world3d` +1 line, `🏗️builder/🧩️app` +151 bytes. Appendix A omitted three files that the closure already contained: `🧪️tests/🧬️generated-test-contracts/🦀️.rs` (100 lines, an unconditional root mount that exports four macros), `🧵️retained-command/♻️metadata/🦀️.rs` (8) and `🪟️window/🎚️config/🧬️preparation/✏️apply/🦀️.rs` (3); two rows (`🪆️child/👁️read/🧪️test-view`, `⚖️authoring-law`) belong to the test and feature closures only. The item graph is unchanged: `plan_tools.py census` prints the same crate sizes as 6.1 for all 41 crates and 196 moves of 3,351 lines (plan 3,352), `home` the same 227 fields / 674 methods / 14,971 lines and the same homing totals.']
    s11 = '\n'.join(t) + '\n'
    s13 = ('* **[WP0 change] State at WP0 start.** The tree had moved since planning: the relocation session had replaced the `ui_wgpu` dependency by `semio-framework-ui-layout` and `semio-framework-ui-declaration` and added the `InstanceExtensions` alias and the `🧵️instance/🧩️extensions` trait file; `PKG/Cargo.toml` and the root were staged by a peer. The trace-testkit change (`RESULT-W4-TRACE-TESTKIT.md`) adds a dev-dependency to 34 crates but not to this one; the root test heap witness still names `semio_framework_trace::HeapWitness`, which still exists. Peers keep editing plugin files (`⚛️reactor`, `🧪️testing`, the instance band files): every package re-reads a file before each edit (12.3), and the root is WP0-owned.\n')
    s61 = ('**[WP0 change] 6.1 as frozen.** A 42nd lower crate, `reactor-tasks` (D8, WP4, root `⚛️reactor/⏲️tasks`, dependencies `actor-host` and `decl-emission`, rank between `reactor-app` and `decl-registry`), exists as a skeleton; `reactor-core` and `reactor-turn` gain a dependency on it. The `†` of a row means that the plan creates the crate root file, not that the directory is new: the roots of `composition-emission`, `extension` and `publication-mounted` are existing directories without a `🦀️.rs`, and `reactor-surfaces` (`⚛️reactor/📥️cold-pair`) has an occupied root (class B, 12.5.2). Appendix H is the authoritative table (rank, work package, class, dependencies).\n')
    s8 = ('**[WP0 change] `ui_wgpu` (D3).** The dependency line and every code mention were already gone when WP0 started (a peer replaced them, see 1.3). Verified: no `ui_wgpu` key in `PKG/Cargo.toml`, a comment- and string-stripped scan of the lib and test closures finds no `ui_wgpu` in code (19 files mention it in comments or strings) and the manifest keeps three historical comment lines that name it. Nothing for WP0 to delete; the compiler confirms at the first real check.\n')
    s122 = ('**[WP0 change] executed 2026-10-15; what it created and the rules that follow are in 12.5.** Deviations from the steps below: step 2 builds 80 skeletons (42 lower, 16 family, 21 bins, `test-support`) and writes no boundary-corpus row (the corpus is the UI area\'s); step 3 does not cut the 11 exported macros, `owned_abi` and `component_persistent_local` out of their files (that would have changed textual macro scope and the equivalence evidence): the three facade macro mount modules exist and the owning package fills them (12.5.6), WP1 cuts the two root regions (12.5.3 rule 2b), the dead `ui_wgpu` line was already gone (D3), the boundary triple is replaced, the hubs are `PLUG/🪝️mounts/<hub>` (the `📥️` of this step collides with the existing `📥️poll` and `📥️receipt` folders); step 4 (S0) is not done by WP0: the owning package makes its own file cut as its first step, because those cuts are disjoint by owner (runtime file, reactor root and `wit_bridge`: WP4; time-travel file: WP5; instance family: WP6, 12.5.9) and the cross-package item moves are prepared as lift files (Appendix J).\n')
    a_rows = ('| `🧪️tests/🧬️generated-test-contracts/🦀️.rs` | 100 | 5 | facade `[WP0 change]` (missing here; unconditional root mount, exports the `__semio_*_fresh_test` macros) |\n'
              '| `🧵️retained-command/♻️metadata/🦀️.rs` | 8 | 0 | retained-command `[WP0 change]` (missing here) |\n'
              '| `🪟️window/🎚️config/🧬️preparation/✏️apply/🦀️.rs` | 3 | 0 | window-config `[WP0 change]` (missing here) |\n')
    blocked = open(G + '/pwp0-blocked.txt', encoding='utf-8').read().strip()
    json.dump(dict(s11=s11, s13=s13, s61=s61, s8=s8, s122=s122, a_rows=a_rows, blocked=blocked), open(G + '/pwp0-results.json', 'w', encoding='utf-8'), ensure_ascii=False, indent=1)
    print('results written')
if __name__ == '__main__': main()
